 const maternal=new T.Group();scene.add(maternal);maternal.visible=false;const wombMaterial=new T.MeshStandardMaterial({color:0xdab5be,transparent:true,opacity:.16,depthWrite:false,side:T.DoubleSide});ell([0,.25,0],[1.1,1.55,.85],wombMaterial,maternal);ell([0,.65,-.68],[.72,.86,.14],new T.MeshStandardMaterial({color:0xc9838d}),maternal);ell([0,-1.25,0],[.24,.38,.22],new T.MeshStandardMaterial({color:0xe5bba7}),maternal);const maternalView=()=>['placenta','cervix'].includes(selected?.type);
