 function label(text,position){const c=document.createElement('canvas');c.width=256;c.height=64;const g=c.getContext('2d');g.fillStyle='#102b35e6';g.fillRect(0,0,256,64);g.font='bold 30px sans-serif';g.textAlign='center';g.fillStyle='#e6f8fa';g.fillText(text,128,43);const m=new T.SpriteMaterial({map:new T.CanvasTexture(c),depthTest:false,transparent:true});const sprite=new T.Sprite(m);sprite.position.set(...position);sprite.userData.label=text;sprite.userData.originalPosition=sprite.position.clone();sprite.scale.set(.23,.058,1);sprite.renderOrder=6;heart.add(sprite);labels.push(sprite);}
